// The Server Object type construct_world's glue, generated by the Crowdy SDK from its definition. Regenerate it; do not edit.
// Your code goes in logic.rs, which implements Functions on ConstructWorldState.
#![allow(non_snake_case, non_camel_case_types, dead_code, unused_imports, unused_variables)]

mod logic;
mod types;

use ckx_sdk::prelude::*;
use std::collections::{BTreeMap, BTreeSet};
pub use types::*;

const CONTRACT: u64 = 1;
const OWNER_ONLY: bool = false;

/// The Server Functions, implemented in logic.rs. A new function appears here first.
pub trait Functions {
    fn list_programs(&mut self, ctx: &Ctx, call: &Call<'_>) -> Result<ListProgramsReply>;
    fn pulse(&mut self, ctx: &Ctx) -> Result<()>;
    fn on_timer(&mut self, ctx: &Ctx, name: &str) -> Result<()> {
        Ok(())
    }
    fn on_topic(&mut self, ctx: &Ctx, msg: TopicMsg<'_>) -> Result<()> {
        Ok(())
    }
    fn on_presence(&mut self, ctx: &Ctx, presence: &Presence) -> Result<()> {
        Ok(())
    }
}

#[derive(Serialize, Deserialize, Default)]
pub struct ServerObject {
    state: ConstructWorldState,
    epoch: u64,
    seq: u64,
}

#[derive(Serialize)]
struct SnapshotOut<'a> {
    contract: u64,
    state: &'a ConstructWorldState,
    timer_kinds: BTreeMap<&'static str, &'static str>,
}

#[derive(Deserialize)]
struct SnapshotIn {
    contract: u64,
    state: ConstructWorldState,
    #[serde(default)]
    timer_kinds: Option<BTreeMap<String, String>>,
}

// Starts and stops the definition's timers, with the period set there; from server code, once its dispatch is kept.
pub mod timers {
    use super::*;
    use std::cell::RefCell;

    // Each timer's Name, so a misspelt one in start or stop does not build.
    pub const PULSE: &str = "Pulse";

    thread_local! {
        static QUEUED: RefCell<Vec<Vec<(String, bool)>>> = const { RefCell::new(Vec::new()) };
    }

    pub(crate) fn open() {
        QUEUED.with(|stack| stack.borrow_mut().push(Vec::new()));
    }

    // Only the last start or stop queued for a timer counts, so a stop queued after a start of it still wins.
    pub(crate) fn close() -> Vec<(String, bool)> {
        let queued = QUEUED.with(|stack| stack.borrow_mut().pop()).unwrap_or_default();
        let mut last: Vec<(String, bool)> = Vec::new();
        for (name, start) in queued {
            last.retain(|(earlier, _)| *earlier != name);
            last.push((name, start));
        }
        last
    }

    // False outside a dispatch, where a start or stop happens at once.
    fn queue(name: &str, start: bool) -> bool {
        QUEUED.with(|stack| stack.borrow_mut().last_mut().map(|queued| queued.push((name.to_string(), start))).is_some())
    }

    // Arms the queued starts in order; when one fails, those armed before it are cancelled and the dispatch is refused.
    pub(crate) fn arm_queued(ctx: &Ctx, queued: &[(String, bool)]) -> Result<()> {
        let starts: Vec<&str> = queued.iter().filter(|(_, start)| *start).map(|(name, _)| name.as_str()).collect();
        for (index, name) in starts.iter().enumerate() {
            let Err(error) = arm(ctx, name) else {
                continue;
            };
            // A timer that was already running is cancelled here, not given back its earlier deadline.
            for armed in &starts[..index] {
                ctx.cancel_timer(armed);
            }
            return Err(Error::new(&format!("the change was not kept: timer {name} could not start: {error}")));
        }
        Ok(())
    }

    pub(crate) fn stop_queued(ctx: &Ctx, queued: &[(String, bool)]) {
        for (name, _) in queued.iter().filter(|(_, start)| !*start) {
            ctx.cancel_timer(name);
        }
    }

    pub(crate) fn arm(ctx: &Ctx, name: &str) -> Result<()> {
        match name {
            "Pulse" => ctx.timer_every("Pulse", 60000),
            other => Err(Error::new(&format!("no timer is named {other}"))),
        }
    }

    // Each timer's Runs and whether it starts automatically; the snapshot keeps the Runs so a deploy that changes one is seen at load.
    const KINDS: &[(&str, &str, bool)] = &[
        ("Pulse", "every:60000", true),
    ];

    pub(crate) fn saved_kinds() -> BTreeMap<&'static str, &'static str> {
        KINDS.iter().map(|&(name, kind, _)| (name, kind)).collect()
    }

    // A pending timer whose Runs changed is armed again under the new Runs, a new one that was pending or starts automatically is armed, a removed one is stopped; a stopped or fired one stays so.
    pub(crate) fn rearm_changed(ctx: &Ctx, saved: &BTreeMap<String, String>) {
        let pending: BTreeSet<String> = ctx.timers().into_iter().map(|(name, _)| name).collect();
        for name in saved.keys().filter(|name| !KINDS.iter().any(|&(kept, _, _)| kept == name.as_str())) {
            ctx.cancel_timer(name);
        }
        for &(name, kind, automatic) in KINDS {
            let rearm = match saved.get(name) {
                Some(old) => old.as_str() != kind && pending.contains(name),
                None => pending.contains(name) || automatic,
            };
            if !rearm {
                continue;
            }
            // Arming replaces a pending timer by name, so a failed arm leaves the old one.
            if let Err(error) = arm(ctx, name) {
                let _ = ctx.log(Level::Warn, &format!("timer {name} keeps any old schedule: the changed one could not be armed: {error}"));
            }
        }
    }

    pub fn start(ctx: &Ctx, name: &str) -> Result<()> {
        if !matches!(name, "Pulse") || !queue(name, true) {
            return arm(ctx, name);
        }
        Ok(())
    }

    /// In a dispatch the stop waits for its success and this answers true; elsewhere, whether the timer was running.
    pub fn stop(ctx: &Ctx, name: &str) -> bool {
        queue(name, false) || ctx.cancel_timer(name)
    }
}

impl Hub for ServerObject {
    fn spawn(ctx: &Ctx, seed: &[u8]) -> Result<Self> {
        if ctx.key != "main" {
            return Err(Error::new("denied: this Server Object has only one instance, whose Instance Id is main"));
        }
        let state = if seed.is_empty() { <ConstructWorldState as Default>::default() } else { decode(seed)? };
        Self::check_watched(&state).map_err(|(field, why)| Error::new(&format!("bad_seed: {field}: the seed holds a value players cannot read: {why}")))?;
        timers::arm(ctx, "Pulse")?;
        Ok(Self { state, epoch: ctx.now_ms() as u64, seq: 0 })
    }

    fn load(ctx: &Ctx, snapshot: &[u8], _from_version: u64) -> Result<Self> {
        if ctx.key != "main" {
            return Err(Error::new("denied: this Server Object has only one instance, whose Instance Id is main"));
        }
        let saved: SnapshotIn = decode(snapshot)?;
        if saved.contract != CONTRACT {
            return Err(Error::new(&format!("the snapshot was written for contract {}, this code reads {}", saved.contract, CONTRACT)));
        }
        if let Some(kinds) = &saved.timer_kinds {
            timers::rearm_changed(ctx, kinds);
        }
        Ok(Self { state: saved.state, epoch: ctx.now_ms() as u64, seq: 0 })
    }

    fn persist(&mut self, _ctx: &Ctx) -> Result<Vec<u8>> {
        encode(&SnapshotOut { contract: CONTRACT, state: &self.state, timer_kinds: timers::saved_kinds() })
    }

    fn handle(&mut self, ctx: &Ctx, call: Call<'_>) -> Result<Vec<u8>> {
        match call.method {
            "read" => {
                authorize(ctx, &call, true)?;
                Self::check_watched(&self.state).map_err(unreadable)?;
                self.read_reply()
            }
            "list_programs" => {
                authorize(ctx, &call, true)?;
                timers::open();
                let before = Clone::clone(&self.state);
                let result = Functions::list_programs(&mut self.state, ctx, &call).and_then(|reply| encode_reply(&reply));
                self.finish(ctx, before, result)
            }
            other => Err(Error::new(&format!("unknown_method: {other}"))),
        }
    }

    fn on_timer(&mut self, ctx: &Ctx, name: &str) -> Result<()> {
        timers::open();
        let before = Clone::clone(&self.state);
        let result = match name {
            "Pulse" => Functions::pulse(&mut self.state, ctx),
            other => Functions::on_timer(&mut self.state, ctx, other),
        };
        self.finish(ctx, before, result)
    }

    fn on_topic(&mut self, ctx: &Ctx, msg: TopicMsg<'_>) -> Result<()> {
        timers::open();
        let before = Clone::clone(&self.state);
        let result = Functions::on_topic(&mut self.state, ctx, msg);
        self.finish(ctx, before, result)
    }

    fn on_presence(&mut self, ctx: &Ctx, presence: &Presence) -> Result<()> {
        timers::open();
        let before = Clone::clone(&self.state);
        let result = Functions::on_presence(&mut self.state, ctx, presence);
        self.finish(ctx, before, result)
    }
}

impl ServerObject {
    // A failed dispatch, an unsendable change or a timer that cannot start leaves the state as it was and publishes nothing.
    fn finish<T>(&mut self, ctx: &Ctx, before: ConstructWorldState, result: Result<T>) -> Result<T> {
        let queued = timers::close();
        // Everything that can fail runs before the change is kept and pushed.
        let prepared = result.and_then(|value| {
            let push = self.prepare_push(&before)?;
            timers::arm_queued(ctx, &queued)?;
            Ok((value, push))
        });
        let (value, push) = match prepared {
            Ok(prepared) => prepared,
            Err(error) => {
                self.state = before;
                return Err(error);
            }
        };
        if let Some(out) = push {
            self.seq += 1;
            let _ = ctx.publish("state", &out);
        }
        timers::stop_queued(ctx, &queued);
        Ok(value)
    }

    // The first watched value an Unreal client could not read, with the field it is in.
    fn check_watched(state: &ConstructWorldState) -> std::result::Result<(), (&'static str, &'static str)> {
        Wire::check(&state.Pulses).map_err(|why| ("Pulses", why))?;
        Wire::check(&state.LastPulseAt).map_err(|why| ("LastPulseAt", why))?;
        Ok(())
    }

    fn read_reply(&self) -> Result<Vec<u8>> {
        let mut out = Vec::new();
        write_map(&mut out, 4);
        write_str(&mut out, "contract");
        write_uint(&mut out, CONTRACT);
        write_str(&mut out, "epoch");
        write_uint(&mut out, self.epoch);
        write_str(&mut out, "seq");
        write_uint(&mut out, self.seq);
        write_str(&mut out, "fields");
        write_map(&mut out, 2);
        write_field(&mut out, "Pulses", &self.state.Pulses)?;
        write_field(&mut out, "LastPulseAt", &self.state.LastPulseAt)?;
        Ok(out)
    }

    fn prepare_push(&self, before: &ConstructWorldState) -> Result<Option<Vec<u8>>> {
        let mut changed: Vec<(&str, Vec<u8>)> = Vec::new();
        if self.state.Pulses != before.Pulses {
            Wire::check(&self.state.Pulses).map_err(|why| unsendable("Pulses", why))?;
            changed.push(("Pulses", encode(&self.state.Pulses)?));
        }
        if self.state.LastPulseAt != before.LastPulseAt {
            Wire::check(&self.state.LastPulseAt).map_err(|why| unsendable("LastPulseAt", why))?;
            changed.push(("LastPulseAt", encode(&self.state.LastPulseAt)?));
        }
        if changed.is_empty() {
            return Ok(None);
        }
        // A push carries a subset of what a read carries, so a read that fits means the push fits too.
        if self.read_reply()?.len() > MAX_MESSAGE {
            return Err(unsendable("the watched values", "together they are larger than 1 MiB"));
        }
        let mut out = Vec::new();
        write_map(&mut out, if OWNER_ONLY { 2 } else { 3 });
        write_str(&mut out, "epoch");
        write_uint(&mut out, self.epoch);
        write_str(&mut out, "seq");
        write_uint(&mut out, self.seq + 1);
        if !OWNER_ONLY {
            write_str(&mut out, "fields");
            write_map(&mut out, changed.len());
            for (name, bytes) in &changed {
                write_str(&mut out, name);
                out.extend_from_slice(bytes);
            }
        }
        Ok(Some(out))
    }
}

// Players may call only player-callable functions, and on an owner-only type only the owner; developer tools and other
// server code may call everything.
fn authorize(ctx: &Ctx, call: &Call<'_>, player_callable: bool) -> Result<()> {
    let Ok(player) = call.player() else {
        return Ok(());
    };
    if !player_callable {
        return Err(Error::new("denied: players may not call this function"));
    }
    if OWNER_ONLY && player.to_string() != ctx.key {
        return Err(Error::new("denied: only the owner may use this Server Object"));
    }
    Ok(())
}

fn bad_params(error: Error) -> Error {
    let text = error.to_string();
    Error::new(&format!("bad_params: {}", text.strip_prefix("decode: ").unwrap_or(&text)))
}

fn write_field<T: Serialize>(out: &mut Vec<u8>, name: &str, value: &T) -> Result<()> {
    write_str(out, name);
    out.extend_from_slice(&encode(value)?);
    Ok(())
}

fn write_map(out: &mut Vec<u8>, len: usize) {
    if len < 16 {
        out.push(0x80 | len as u8);
    } else {
        out.push(0xde);
        out.extend_from_slice(&(len as u16).to_be_bytes());
    }
}

fn write_str(out: &mut Vec<u8>, text: &str) {
    let len = text.len();
    if len < 32 {
        out.push(0xa0 | len as u8);
    } else if len < 256 {
        out.push(0xd9);
        out.push(len as u8);
    } else {
        out.push(0xda);
        out.extend_from_slice(&(len as u16).to_be_bytes());
    }
    out.extend_from_slice(text.as_bytes());
}

fn write_uint(out: &mut Vec<u8>, value: u64) {
    if value < 128 {
        out.push(value as u8);
    } else if value < 256 {
        out.push(0xcc);
        out.push(value as u8);
    } else if value < 65536 {
        out.push(0xcd);
        out.extend_from_slice(&(value as u16).to_be_bytes());
    } else if value < 4294967296 {
        out.push(0xce);
        out.extend_from_slice(&(value as u32).to_be_bytes());
    } else {
        out.push(0xcf);
        out.extend_from_slice(&value.to_be_bytes());
    }
}

type Checked = std::result::Result<(), &'static str>;

const MAX_MESSAGE: usize = 1024 * 1024;
const MAX_ELEMENTS: usize = 4096;
const MAX_MESSAGE_ELEMENTS: usize = 65536;
const MAX_TEXT: usize = 65535;

// Values an Unreal client would refuse to read: the glue keeps them out of watched fields, replies and accepted params.
trait Wire {
    fn check(&self) -> Checked;

    // Elements of every list, set and map in the value, nested ones included, a map entry once: as an Unreal client counts them.
    fn elements(&self) -> usize {
        0
    }
}

// How two set elements or map keys compare in Unreal, where text ignores case.
trait WireKey: Ord {
    fn folded(&self) -> Option<String> {
        None
    }
}

macro_rules! wire_always_ok {
    ($($t:ty),*) => {
        $(impl Wire for $t {
            fn check(&self) -> Checked {
                Ok(())
            }
        })*
    };
}
wire_always_ok!(bool, i8, i16, i32, i64, u8, u16, u32, u64);

macro_rules! wire_key_exact {
    ($($t:ty),*) => {
        $(impl WireKey for $t {})*
    };
}
wire_key_exact!(i8, i16, i32, i64, u8, u16, u32, u64);

impl Wire for f32 {
    fn check(&self) -> Checked {
        if self.is_finite() { Ok(()) } else { Err("a number is not finite") }
    }
}

impl Wire for f64 {
    fn check(&self) -> Checked {
        if self.is_finite() { Ok(()) } else { Err("a number is not finite") }
    }
}

impl Wire for String {
    fn check(&self) -> Checked {
        if self.len() <= MAX_TEXT { Ok(()) } else { Err("a text is longer than 65535 bytes") }
    }
}

impl WireKey for String {
    // Unreal keys two texts as one when they have the same length and the same compared part.
    fn folded(&self) -> Option<String> {
        Some(format!("{}\0{}", compared_part(self), utf16_len(self)))
    }
}

impl<T: Wire> Wire for Option<T> {
    fn check(&self) -> Checked {
        match self {
            Some(value) => value.check(),
            None => Ok(()),
        }
    }

    fn elements(&self) -> usize {
        self.as_ref().map_or(0, Wire::elements)
    }
}

impl<T: Wire> Wire for Vec<T> {
    fn check(&self) -> Checked {
        if self.len() > MAX_ELEMENTS {
            return Err("a list has more than 4096 elements");
        }
        self.iter().try_for_each(|value| value.check())
    }

    fn elements(&self) -> usize {
        self.len() + self.iter().map(Wire::elements).sum::<usize>()
    }
}

impl<T: Wire + WireKey> Wire for BTreeSet<T> {
    fn check(&self) -> Checked {
        if self.len() > MAX_ELEMENTS {
            return Err("a set has more than 4096 elements");
        }
        self.iter().try_for_each(|value| value.check())?;
        check_folded(self.iter())
    }

    fn elements(&self) -> usize {
        self.len()
    }
}

impl<K: Wire + WireKey, V: Wire> Wire for BTreeMap<K, V> {
    fn check(&self) -> Checked {
        if self.len() > MAX_ELEMENTS {
            return Err("a map has more than 4096 entries");
        }
        self.keys().try_for_each(|key| key.check())?;
        self.values().try_for_each(|value| value.check())?;
        check_folded(self.keys())
    }

    fn elements(&self) -> usize {
        self.len() + self.values().map(Wire::elements).sum::<usize>()
    }
}

fn check_folded<'a, K: WireKey + 'a>(keys: impl Iterator<Item = &'a K>) -> Checked {
    let mut seen = BTreeSet::new();
    for key in keys {
        let Some(folded) = key.folded() else {
            return Ok(());
        };
        if !seen.insert(folded) {
            return Err("two keys are one key in Unreal, which ignores the case of ASCII letters");
        }
    }
    Ok(())
}

fn unsendable(what: &str, why: &str) -> Error {
    Error::new(&format!("the change was not kept: {what}: {why}"))
}

// Refuses a read until server code replaces the value, such as one restored from a save that players cannot read.
fn unreadable((field, why): (&str, &str)) -> Error {
    Error::new(&format!("unreadable: {field}: the server state holds a value players cannot read: {why}"))
}

fn encode_reply<T: Serialize + Wire>(reply: &T) -> Result<Vec<u8>> {
    Wire::check(reply).map_err(|why| unsendable("the reply", why))?;
    if reply.elements() > MAX_MESSAGE_ELEMENTS {
        return Err(unsendable("the reply", "it holds more than 65536 elements"));
    }
    let bytes = encode(reply)?;
    if bytes.len() > MAX_MESSAGE {
        return Err(unsendable("the reply", "it is larger than 1 MiB"));
    }
    Ok(bytes)
}

const MIN_DATE_MS: i64 = -62135596800000;
const MAX_DATE_MS: i64 = 253402300799999;
const MIN_TIMESPAN_MS: i64 = -922337203685477;
const MAX_TIMESPAN_MS: i64 = 922337203685477;
const MAX_NAME: usize = 1023;

// Unreal holds text as UTF-16, so it counts a text's length in UTF-16 units.
fn utf16_len(text: &str) -> usize {
    text.chars().map(char::len_utf16).sum()
}

// What Unreal compares of a text: the part before any NUL, ignoring the case of ASCII letters only.
fn compared_part(text: &str) -> String {
    text.split('\0').next().unwrap_or("").to_ascii_lowercase()
}

fn check_name(text: &str) -> Checked {
    if utf16_len(text) <= MAX_NAME { Ok(()) } else { Err("a name is longer than 1023 characters") }
}

// Unreal names that differ only in ASCII case or after a NUL are one name, and an empty name is None.
fn check_name_keys<'a>(keys: impl Iterator<Item = &'a String>) -> Checked {
    let mut seen = BTreeSet::new();
    for key in keys {
        let part = compared_part(key);
        if !seen.insert(if part.is_empty() { String::from("none") } else { part }) {
            return Err("two names are one name in Unreal, which ignores the case of ASCII letters and reads an empty name as None");
        }
    }
    Ok(())
}

// Whether a tag exists only the client knows; one this long cannot.
fn check_tag(text: &str) -> Checked {
    if utf16_len(text) <= MAX_NAME { Ok(()) } else { Err("a gameplay tag is longer than 1023 characters") }
}

// The forms FGuid::Parse reads besides its Base64 and Base36 ones, # standing for a hex digit.
const GUID_FORMS: [&str; 6] = [
    "################################",
    "########-####-####-####-############",
    "{########-####-####-####-############}",
    "(########-####-####-####-############)",
    "########-########-########-########",
    "{0x########,0x####,0x####,{0x##,0x##,0x##,0x##,0x##,0x##,0x##,0x##}}",
];

fn check_guid(text: &str) -> Checked {
    let bytes = text.as_bytes();
    let fits = |form: &&str| {
        form.len() == bytes.len() && form.bytes().zip(bytes).all(|(want, got)| if want == b'#' { got.is_ascii_hexdigit() } else { *got == want })
    };
    let base64 = bytes.len() == 22 && bytes.iter().all(|got| got.is_ascii_alphanumeric() || b"+/-_".contains(got));
    let base36 = bytes.len() == 25 && bytes.iter().all(|got| got.is_ascii_digit() || got.is_ascii_uppercase());
    if base64 || base36 || GUID_FORMS.iter().any(fits) { Ok(()) } else { Err("a GUID is not in a form Unreal reads") }
}

// FPackageName::IsValidObjectPath, less its check that the path's root is mounted, which only the client knows.
fn check_path(text: &str) -> Checked {
    if utf16_len(text) > MAX_NAME {
        return Err("an object path is longer than 1023 characters");
    }
    let (package, object) = text.split_once('.').unwrap_or((text, ""));
    let package_ok = utf16_len(package) >= 4 && package.starts_with('/') && !package.ends_with('/') && !package.contains("//")
        && !package.contains(|c: char| "\\:*?\"<>|' ,.&!~\n\r\t@#".contains(c));
    let object_ok = !object.contains(|c: char| "\"' ,|&!~\n\r\t@#(){}[]=;^%$`/".contains(c)) && !object.ends_with(':');
    if text.is_empty() || (package_ok && object_ok && !text.ends_with('.')) { Ok(()) } else { Err("a text is not an object path") }
}

fn check_date(ms: &i64) -> Checked {
    if (MIN_DATE_MS..=MAX_DATE_MS).contains(ms) { Ok(()) } else { Err("a date is outside the years 1 to 9999") }
}

fn check_timespan(ms: &i64) -> Checked {
    if (MIN_TIMESPAN_MS..=MAX_TIMESPAN_MS).contains(ms) { Ok(()) } else { Err("a timespan is longer than Unreal holds") }
}

impl Wire for ConstructWorldState {
    fn check(&self) -> Checked {
        Wire::check(&self.Pulses)?;
        Wire::check(&self.LastPulseAt)?;
        Ok(())
    }
}

impl Wire for ListProgramsReply {
    fn check(&self) -> Checked {
        Wire::check(&self.Programs)?;
        Ok(())
    }

    fn elements(&self) -> usize {
        self.Programs.elements()
    }
}

impl Wire for ConstructHubProgram {
    fn check(&self) -> Checked {
        Wire::check(&self.ProgramId)?;
        Wire::check(&self.SceneId)?;
        Wire::check(&self.Name)?;
        Wire::check(&self.Description)?;
        Ok(())
    }
}

ckx_sdk::export_hub!(ServerObject);
